CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS workflows (id UUID PRIMARY KEY, request_id UUID UNIQUE NOT NULL, workflow_type TEXT NOT NULL, logical_specialist_id TEXT NOT NULL, runtime_id TEXT NULL, status TEXT NOT NULL, validation_required BOOLEAN NULL, effective_classification TEXT NOT NULL DEFAULT 'PUBLIC', failure_code TEXT NULL, failure_message TEXT NULL, objective TEXT NOT NULL DEFAULT '', context JSONB NOT NULL DEFAULT '{}'::jsonb, requires_implementation BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS artifacts (id UUID PRIMARY KEY, workflow_id UUID NOT NULL REFERENCES workflows(id), artifact_type TEXT NOT NULL, content_type TEXT NOT NULL, storage_ref TEXT NULL, content_json JSONB NULL, content_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workflow_stages (id UUID PRIMARY KEY, workflow_id UUID NOT NULL REFERENCES workflows(id), logical_stage_key TEXT NOT NULL, stage_type TEXT NOT NULL, runtime_id TEXT NULL, status TEXT NOT NULL, attempt INTEGER NOT NULL, external_execution_id TEXT NULL, input_artifact_id UUID NULL, output_artifact_id UUID NULL, started_at TIMESTAMPTZ NULL, completed_at TIMESTAMPTZ NULL, error_code TEXT NULL, error_message TEXT NULL, UNIQUE(workflow_id,logical_stage_key), UNIQUE(workflow_id,stage_type,attempt));
CREATE TABLE IF NOT EXISTS workflow_events (id UUID PRIMARY KEY, workflow_id UUID NOT NULL REFERENCES workflows(id), sequence BIGINT NOT NULL, event_type TEXT NOT NULL, actor_type TEXT NOT NULL, actor_id TEXT NOT NULL, stage_id UUID NULL, metadata JSONB NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(workflow_id,sequence));
CREATE TABLE IF NOT EXISTS workflow_attempts (id UUID PRIMARY KEY, workflow_id UUID NOT NULL REFERENCES workflows(id), stage_id UUID NULL REFERENCES workflow_stages(id), logical_stage_key TEXT NOT NULL, attempt_number INTEGER NOT NULL, owner_id TEXT NOT NULL, status TEXT NOT NULL, initiation_evidence JSONB NULL, terminal_evidence JSONB NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(workflow_id,logical_stage_key), UNIQUE(stage_id,attempt_number));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_attempt_per_stage ON workflow_attempts(workflow_id,logical_stage_key) WHERE status IN ('CLAIMED','STARTING','RUNNING','STATUS_UNKNOWN');
CREATE TABLE IF NOT EXISTS request_idempotency (caller_id TEXT NOT NULL, operation TEXT NOT NULL, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, workflow_id UUID NOT NULL REFERENCES workflows(id), result_reference TEXT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(caller_id,operation,idempotency_key));
CREATE OR REPLACE FUNCTION reject_workflow_event_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'workflow_events is append-only'; END; $$;
DROP TRIGGER IF EXISTS workflow_events_no_update ON workflow_events; CREATE TRIGGER workflow_events_no_update BEFORE UPDATE OR DELETE ON workflow_events FOR EACH ROW EXECUTE FUNCTION reject_workflow_event_mutation();
